import math

def min_Jumps(d: float, length: float) -> int:
    if d == 0:
        return 0
    if length == 0:
        return 0 if d == 0 else float('inf')  # Can't move if length=0 and d>0

    if d == length:
        return 1
    if d < length:
        # One jump overshoots but we can't shorten the jump,
        # so we need at least 2 jumps (e.g., one jump away then one jump back to (d,0))
        return 2
    # Otherwise, minimum jumps is ceil(d/length)
    return math.ceil(d / length)

