def circular_shift(x, shift):
    s = str(x)
    n = len(s)
    if abs(shift) >= n:
        return s[::-1]
    # Positive shift means rotate right
    # Negative shift means rotate left
    if shift > 0:
        shift = shift % n
        return s[-shift:] + s[:-shift]
    elif shift < 0:
        shift = (-shift) % n
        return s[shift:] + s[:shift]
    else:
        return s

