    def sorted_word(word):
        # Sort characters only if there is at least one letter or digit
        # If word contains no letters/digits (e.g. "!!!"), leave as is
        if any(c.isalnum() for c in word):
            return ''.join(sorted(word))
        else:
            return word

    return ''.join(sorted_word(part) if part.strip() else part for part in parts)

